647|int parse_options(int argc, char *argv[])
648|{
649|	int short_option;
650|	int option_index = 1;
651|	FLAC__bool had_error = false;
652|	const char *short_opts = "0123456789aA:b:cdefFhHl:mMo:pP:q:r:sS:tT:vVw";
653|
654|	while ((short_option = share__getopt_long(argc, argv, short_opts, long_options_, &option_index)) != -1) {
655|		switch (short_option) {
656|			case 0: /* long option with no equivalent short option */
657|				had_error |= (parse_option(short_option, long_options_[option_index].name, share__optarg) != 0);
658|				break;
659|			case '?':
660|			case ':':
661|				had_error = true;
662|				break;
663|			default: /* short option */
664|				had_error |= (parse_option(short_option, 0, share__optarg) != 0);
665|				break;
666|		}
667|	}
668|
669|	if(had_error) {
670|		return 1;
671|	}
672|
673|	FLAC__ASSERT(share__optind <= argc);
674|
675|	option_values.num_files = argc - share__optind;
676|
677|	if(option_values.num_files > 0) {
678|		uint32_t i = 0;
679|		if(0 == (option_values.filenames = malloc(sizeof(char*) * option_values.num_files)))
680|			die("out of memory allocating space for file names list");
681|		while(share__optind < argc)
682|			option_values.filenames[i++] = local_strdup(argv[share__optind++]);
683|	}
684|
685|	return 0;
686|}

161|FLAC__bool parse_options(int argc, char *argv[], CommandLineOptions *options)
162|{
163|	int ret;
164|	int option_index = 1;
165|	FLAC__bool had_error = false;
166|
167|	while ((ret = share__getopt_long(argc, argv, "", long_options_, &option_index)) != -1) {
168|		switch (ret) {
169|			case 0:
170|				had_error |= !parse_option(option_index, share__optarg, options);
171|				break;
172|			case '?':
173|			case ':':
174|				had_error = true;
175|				break;
176|			default:
177|				FLAC__ASSERT(0);
178|				break;
179|		}
180|	}
181|
182|	if(options->prefix_with_filename == 2)
183|		options->prefix_with_filename = (argc - share__optind > 1);
184|
185|	if(share__optind >= argc && !options->show_long_help && !options->show_version) {
186|		flac_fprintf(stderr,"ERROR: you must specify at least one FLAC file;\n");
187|		flac_fprintf(stderr,"       metaflac cannot be used as a pipe\n");
188|		had_error = true;
189|	}
190|
191|	options->num_files = argc - share__optind;
192|
193|	if(options->num_files > 0) {
194|		unsigned i = 0;
195|		if(0 == (options->filenames = safe_malloc_mul_2op_(sizeof(char*), /*times*/options->num_files)))
196|			die("out of memory allocating space for file names list");
197|		while(share__optind < argc)
198|			options->filenames[i++] = local_strdup(argv[share__optind++]);
199|	}
200|
201|	if(options->args.checks.num_major_ops > 0) {
202|		if(options->args.checks.num_major_ops > 1) {
203|			flac_fprintf(stderr, "ERROR: you may only specify one major operation at a time\n");
204|			had_error = true;
205|		}
206|		else if(options->args.checks.num_shorthand_ops > 0) {
207|			flac_fprintf(stderr, "ERROR: you may not mix shorthand and major operations\n");
208|			had_error = true;
209|		}
210|	}
211|
212|	/* check for only one FLAC file used with certain options */
213|	if(options->num_files > 1) {
214|		if(0 != find_shorthand_operation(options, OP__IMPORT_CUESHEET_FROM)) {
215|			flac_fprintf(stderr, "ERROR: you may only specify one FLAC file when using '--import-cuesheet-from'\n");
216|			had_error = true;
217|		}
218|		if(0 != find_shorthand_operation(options, OP__EXPORT_CUESHEET_TO)) {
219|			flac_fprintf(stderr, "ERROR: you may only specify one FLAC file when using '--export-cuesheet-to'\n");
220|			had_error = true;
221|		}
222|		if(0 != find_shorthand_operation(options, OP__EXPORT_PICTURE_TO)) {
223|			flac_fprintf(stderr, "ERROR: you may only specify one FLAC file when using '--export-picture-to'\n");
224|			had_error = true;
225|		}
226|		if(
227|			0 != find_shorthand_operation(options, OP__IMPORT_VC_FROM) &&
228|			0 == strcmp(find_shorthand_operation(options, OP__IMPORT_VC_FROM)->argument.filename.value, "-")
229|		) {
230|			flac_fprintf(stderr, "ERROR: you may only specify one FLAC file when using '--import-tags-from=-'\n");
231|			had_error = true;
232|		}
233|	}
234|
235|	if(options->args.checks.has_block_type && options->args.checks.has_except_block_type) {
236|		flac_fprintf(stderr, "ERROR: you may not specify both '--block-type' and '--except-block-type'\n");
237|		had_error = true;
238|	}
239|
240|	if(had_error)
241|		short_usage(0);
242|
243|	/*
244|	 * We need to create an OP__ADD_SEEKPOINT operation if there is
245|	 * not one already, and --import-cuesheet-from was specified but
246|	 * --no-cued-seekpoints was not:
247|	 */
248|	if(options->cued_seekpoints) {
249|		Operation *op = find_shorthand_operation(options, OP__IMPORT_CUESHEET_FROM);
250|		if(0 != op) {
251|			Operation *op2 = find_shorthand_operation(options, OP__ADD_SEEKPOINT);
252|			if(0 == op2)
253|				op2 = append_shorthand_operation(options, OP__ADD_SEEKPOINT);
254|			op->argument.import_cuesheet_from.add_seekpoint_link = &(op2->argument.add_seekpoint);
255|		}
256|	}
257|
258|	return had_error;
259|}

